def squash(s: str) -> str:
    n = len(s)
    if n == 0:
        return ""
    parts = []
    i = 0
    while i < n:
        c = s[i]
        j = i + 1
        while j < n and s[j] == c:
            j += 1
        run = j - i
        esc = "\\" + c if c == "\\" or ("0" <= c <= "9") else c
        if run >= 3:
            parts.append(str(run))
            parts.append(esc)
        else:
            parts.append(esc * run)
        i = j
    return "".join(parts)
